local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();local t=p:GetCurrentTimeline();assert(t:GetName()=='v7 V3 Creative - tightened master');assert(not p:IsRenderingInProgress());local clips=t:GetItemListInTrack('audio',1);local n=0;for _,c in ipairs(clips) do assert(c:SetFades({FadeIn=1,FadeOut=1}));n=n+1 end;print('EDGE_FADES',n);r:GetProjectManager():SaveProject();p:SetRenderSettings({CustomName='narration-tight-resolve-smooth'});local id=p:AddRenderJob();print('VOICE_SMOOTH_JOB',id);print('STARTED',p:StartRendering(id))